import pandas as pd
import numpy as np
import re

# 读取右侧数据
right_file = '/tmp/data/task_pdxzon4_/dataset/TA/tables/english_table/Deflection_Value_Record_Table/Deflection_Value_Record_Table_Right_of_Minzhu_Road.csv'
right_df = pd.read_csv(right_file, header=None, skiprows=1, nrows=32)

# 解析右侧数据
def parse_right_data(df):
    data = []
    for idx, row in df.iterrows():
        if pd.notna(row[0]):
            data.append({
                'pile_number': row[0],
                'reading_left': row[1],
                'reading_right': row[2],
                'deflection_left': row[3],
                'deflection_right': row[4]
            })
        if pd.notna(row[6]):
            data.append({
                'pile_number': row[6],
                'reading_left': row[7],
                'reading_right': row[8],
                'deflection_left': row[9],
                'deflection_right': row[10]
            })
    return pd.DataFrame(data)

right_data = parse_right_data(right_df)

# 转换桩号
def convert_pile_number(pile_str):
    if pd.isna(pile_str):
        return None
    match = re.match(r'K(\d+)\+(\d+)', str(pile_str))
    if match:
        return int(match.group(1)) * 1000 + int(match.group(2))
    return None

right_data['pile_value'] = right_data['pile_number'].apply(convert_pile_number)
right_data = right_data.sort_values('pile_value')

print("=" * 80)
print("民主路右侧挠度数据 - K2+100位置分析")
print("=" * 80)

# 查找K2+100附近的数据
target_pile = 2100  # K2+100
k2_100_data = right_data[right_data['pile_value'] == target_pile]

print(f"\nK2+100位置数据查找:")
if len(k2_100_data) > 0:
    print(f"找到K2+100位置的数据:")
    for idx, row in k2_100_data.iterrows():
        print(f"  桩号: {row['pile_number']}")
        print(f"  左侧读数: {row['reading_left']}, 右侧读数: {row['reading_right']}")
        print(f"  左侧挠度: {row['deflection_left']}, 右侧挠度: {row['deflection_right']}")
else:
    print(f"未找到K2+100位置的数据，查找K2+100附近的桩点...")
    # 查找K2+100附近50米范围内的数据
    nearby_data = right_data[(right_data['pile_value'] >= target_pile - 50) & (right_data['pile_value'] <= target_pile + 50)]
    print(f"\nK2+100附近50米范围内的数据:")
    for idx, row in nearby_data.iterrows():
        print(f"  {row['pile_number']}: 左侧{row['deflection_left']}, 右侧{row['deflection_right']}")
"}

